const clock = new THREE.Clock();
scene.background = new THREE.Color(0xf4f7fb);
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.08;
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;

const keyLight = new THREE.DirectionalLight(0xffffff, 1.35);
keyLight.position.set(6, 10, 8);
keyLight.castShadow = true;
keyLight.shadow.mapSize.width = 2048;
keyLight.shadow.mapSize.height = 2048;
keyLight.shadow.camera.near = 0.1;
keyLight.shadow.camera.far = 50;
keyLight.shadow.bias = -0.001;

const fillLight = new THREE.DirectionalLight(0xbfd7ff, 0.55);
fillLight.position.set(-7, 4, 5);

const rimLight = new THREE.PointLight(0xaad6ff, 0.45, 22);
rimLight.position.set(-4, 3, -5);

const warmAccent = new THREE.PointLight(0xffaa77, 0.6, 15);
warmAccent.position.set(2, 6, -3);

scene.add(new THREE.AmbientLight(0x7f8aa6, 0.32), keyLight, fillLight, rimLight, warmAccent);

const floor = new THREE.Mesh(
  new THREE.CircleGeometry(18, 96),
  new THREE.MeshStandardMaterial({ color: 0xe6ecf5, roughness: 0.92, metalness: 0.02 })
);
floor.rotation.x = -Math.PI / 2;
floor.position.y = -3.5;
floor.receiveShadow = true;
scene.add(floor);

const hypothesisGroup = new THREE.Group();
scene.add(hypothesisGroup);

const surfaceMaterial = new THREE.MeshPhysicalMaterial({
  color: 0xffffff,
  metalness: 0.1,
  roughness: 0.2,
  transmission: 0.15,
  thickness: 0.5,
  clearcoat: 0.8,
  clearcoatRoughness: 0.1,
  side: THREE.DoubleSide
});

const geometry = new THREE.PlaneGeometry(16, 12, 128, 96);
const positions = geometry.attributes.position;
const colors = [];
const color1 = new THREE.Color(0x4a90e2);
const color2 = new THREE.Color(0x7b68ee);
const color3 = new THREE.Color(0xff6b6b);

for (let i = 0; i < positions.count; i++) {
  const x = positions.getX(i);
  const y = positions.getY(i);

  const dist = Math.sqrt(x * x + y * y);
  const zetaHeight = Math.sin(x * 2) * Math.cos(y * 1.5) * Math.exp(-dist * 0.15) * 2.5;
  const criticalMod = Math.exp(-Math.pow(x - 2, 2) * 4) * Math.sin(y * 3) * 1.5;

  positions.setZ(i, zetaHeight + criticalMod);

  const mixFactor = (zetaHeight + 2.5) / 5;
  const vertexColor = new THREE.Color().lerpColors(color1, color2, mixFactor);
  if (Math.abs(x - 2) < 0.3) vertexColor.lerp(color3, 0.6);
  colors.push(vertexColor.r, vertexColor.g, vertexColor.b);
}

geometry.setAttribute('color', new THREE.Float32BufferAttribute(colors, 3));
geometry.computeVertexNormals();

const zetaSurface = new THREE.Mesh(geometry, surfaceMaterial);
zetaSurface.rotation.x = -Math.PI / 2;
zetaSurface.position.y = 0;
zetaSurface.castShadow = true;
zetaSurface.receiveShadow = true;
hypothesisGroup.add(zetaSurface);

const criticalLineGeo = new THREE.BoxGeometry(0.15, 0.15, 12);
const criticalLineMat = new THREE.MeshPhysicalMaterial({
  color: 0xff4757,
  emissive: 0xff4757,
  emissiveIntensity: 0.4,
  metalness: 0.8,
  roughness: 0.2
});
const criticalLine = new THREE.Mesh(criticalLineGeo, criticalLineMat);
criticalLine.position.set(2, 0.1, 0);
criticalLine.castShadow = true;
hypothesisGroup.add(criticalLine);

const zeroGroup = new THREE.Group();
hypothesisGroup.add(zeroGroup);

const zeroMaterial = new THREE.MeshPhysicalMaterial({
  color: 0xff2e63,
  emissive: 0xff2e63,
  emissiveIntensity: 0.6,
  metalness: 0.9,
  roughness: 0.1,
  clearcoat: 1.0
});

const zeroPositions = [
  { y: -4.5, scale: 0.4 },
  { y: -2.8, scale: 0.5 },
  { y: -1.2, scale: 0.45 },
  { y: 0.8, scale: 0.55 },
  { y: 2.5, scale: 0.48 },
  { y: 4.2, scale: 0.52 }
];

zeroPositions.forEach((pos, idx) => {
  const sphere = new THREE.Mesh(
    new THREE.SphereGeometry(pos.scale, 32, 32),
    zeroMaterial.clone()
  );
  sphere.position.set(2, 0.2, pos.y);
  sphere.castShadow = true;
  sphere.userData = { originalScale: pos.scale, index: idx };
  zeroGroup.add(sphere);

  const glow = new THREE.Mesh(
    new THREE.SphereGeometry(pos.scale * 1.8, 16, 16),
    new THREE.MeshBasicMaterial({
      color: 0xff2e63,
      transparent: true,
      opacity: 0.15
    })
  );
  glow.position.copy(sphere.position);
  zeroGroup.add(glow);
});

const implicationNodes = [];
const implications = [
  { label: "Cryptography", pos: new THREE.Vector3(-5, 3, -3), color: 0x2ed573 },
  { label: "Quantum Chaos", pos: new THREE.Vector3(6, 4, 2), color: 0x1e90ff },
  { label: "Prime Distribution", pos: new THREE.Vector3(-4, 2, 4), color: 0xffa502 },
  { label: "Random Matrices", pos: new THREE.Vector3(5, 3.5, -4), color: 0x9b59b6 }
];

implications.forEach((imp, i) => {
  const nodeGroup = new THREE.Group();
  nodeGroup.position.copy(imp.pos);

  const core = new THREE.Mesh(
    new THREE.IcosahedronGeometry(0.6, 2),
    new THREE.MeshPhysicalMaterial({
      color: imp.color,
      emissive: imp.color,
      emissiveIntensity: 0.3,
      metalness: 0.7,
      roughness: 0.3,
      clearcoat: 0.8
    })
  );
  core.castShadow = true;
  nodeGroup.add(core);

  const ring = new THREE.Mesh(
    new THREE.TorusGeometry(1.0, 0.05, 16, 64),
    new THREE.MeshBasicMaterial({ color: imp.color, transparent: true, opacity: 0.6 })
  );
  ring.rotation.x = Math.PI / 2;
  nodeGroup.add(ring);

  const particleCount = 20;
  const particles = new THREE.InstancedMesh(
    new THREE.SphereGeometry(0.08, 8, 8),
    new THREE.MeshBasicMaterial({ color: imp.color }),
    particleCount
  );

  const dummy = new THREE.Object3D();
  for (let j = 0; j < particleCount; j++) {
    const angle = (j / particleCount) * Math.PI * 2;
    const radius = 1.2 + Math.random() * 0.5;
    dummy.position.set(Math.cos(angle) * radius, Math.sin(angle) * radius * 0.3, Math.sin(angle) * radius);
    dummy.updateMatrix();
    particles.setMatrixAt(j, dummy.matrix);
  }
  nodeGroup.add(particles);

  const lineMaterial = new THREE.LineBasicMaterial({ 
    color: imp.color, 
    transparent: true, 
    opacity: 0.4,
    linewidth: 2 
  });
  const lineGeo = new THREE.BufferGeometry().setFromPoints([
    imp.pos,
    new THREE.Vector3(2, 0.2, imp.pos.z * 0.3)
  ]);
  const connection = new THREE.Line(lineGeo, lineMaterial);
  hypothesisGroup.add(connection);

  implicationNodes.push({ 
    group: nodeGroup, 
    core: core, 
    ring: ring, 
    particles: particles,
    basePos: imp.pos.clone(),
    phase: i * Math.PI / 2
  });
  hypothesisGroup.add(nodeGroup);
});

const particleCount = 200;
const numberFlow = new THREE.InstancedMesh(
  new THREE.OctahedronGeometry(0.08, 0),
  new THREE.MeshStandardMaterial({ 
    color: 0x6c7ae0, 
    metalness: 0.6, 
    roughness: 0.4,
    emissive: 0x4a90e2,
    emissiveIntensity: 0.2
  }),
  particleCount
);
const dummy = new THREE.Object3D();
for (let i = 0; i < particleCount; i++) {
  dummy.position.set(
    (Math.random() - 0.5) * 20,
    Math.random() * 8 - 2,
    (Math.random() - 0.5) * 16
  );
  dummy.rotation.set(Math.random() * Math.PI, Math.random() * Math.PI, 0);
  const scale = 0.5 + Math.random() * 0.8;
  dummy.scale.set(scale, scale, scale);
  dummy.updateMatrix();
  numberFlow.setMatrixAt(i, dummy.matrix);
}
hypothesisGroup.add(numberFlow);

camera.position.set(8, 5, 10);
camera.lookAt(0, 0, 0);

const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.dampingFactor = 0.05;
controls.minDistance = 5;
controls.maxDistance = 20;
controls.maxPolarAngle = Math.PI / 2 - 0.1;

function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();

  hypothesisGroup.rotation.y = Math.sin(t * 0.05) * 0.1;

  zeroGroup.children.forEach((child, i) => {
    if (child.userData.originalScale) {
      const pulse = 1 + Math.sin(t * 2 + i * 0.8) * 0.15;
      child.scale.setScalar(child.userData.originalScale * pulse);
      child.material.emissiveIntensity = 0.6 + Math.sin(t * 3 + i) * 0.2;
    }
  });

  implicationNodes.forEach((node, i) => {
    node.group.position.y = node.basePos.y + Math.sin(t * 0.8 + node.phase) * 0.3;
    node.core.rotation.x = t * 0.3;
    node.core.rotation.y = t * 0.5;
    node.ring.rotation.z = t * 0.2;
    node.ring.scale.setScalar(1 + Math.sin(t * 2 + node.phase) * 0.1);
  });

  numberFlow.rotation.y = t * 0.05;

  rimLight.intensity = 0.35 + Math.sin(t * 1.2) * 0.08;
  warmAccent.intensity = 0.6 + Math.sin(t * 0.7) * 0.1;

  controls.update();
  renderer.render(scene, camera);
}
animate();

